+const assert = require("node:assert/strict");
+const fs = require("node:fs/promises");
+const path = require("node:path");
+const { test } = require("node:test");
+const { chromium, webkit } = require("playwright");
+
+const assets = path.resolve(__dirname, "../assets");
+const now = Date.now();
+const iso = (time) => new Date(time).toISOString();
+const keptDay = iso(now - 864e5).slice(0, 10);
+const seat = (provider, model, who = "") => ({
+  id: who ? `${provider}#${model}` : provider, provider, name: provider, model, who,
+  kind: who ? "key" : "provider",
+});
+const liveOrder = [
+  seat("relay", "opus"),
+  seat("wallet", "codex"),
+  seat("pool", "pool-a", "Primary"),
+  seat("pool", "pool-b", "Second"),
+  seat("ambiguous", "pool-c", "Same name"),
+  seat("missing", "unread"),
+  seat("failed", "read-failed"),
+];
+const route = (order, time) => ({
+  id: 7, seq: 7, time, agent: "codex", model: order[0].model, provider: order[0].provider,
+  done: true, status: 200, ms: 900, tokens: 1500, order,
+  tries: [
+    { id: "relay", model: "opus", start: time, done: true, ms: 200, status: 402, fail: "quota" },
+    ...order.slice(1).map((entry) => ({ id: entry.id, model: entry.model, start: time, done: true, ms: 800, status: 200 })),
+  ],
+});
+const balance = (provider, amount, fields = {}) => ({
+  provider, name: provider, balance: amount, readAt: iso(now - 3000), windows: [], ...fields,
+});
+const cards = (fresh) => [
+  balance("relay", fresh ? "$4.20" : "$-2.50", fresh ? {} : { asOf: iso(now - 6000), readError: "Vendor timed out" }),
+  balance("wallet", "$37.25", { kind: "balance" }),
+  balance("pool", "$42.35", { user: "Second", balanceParts: [{ label: "Wallet", text: "$42.35" }, { label: "Credit", text: "$0.25" }] }),
+  balance("pool", "$0.00", { user: "Primary" }),
+  balance("ambiguous", "$21.09", { user: "Same name" }),
+  balance("ambiguous", "$31.09", { user: "Same name" }),
+  balance("missing", "$190.00", { from: "another computer", kind: "balance" }),
+  balance("failed", "", { error: "Balance API unavailable" }),
+];
+
+function serve(lang, refreshes) {
+  return async (request) => {
+    const url = new URL(request.request().url());
+    const json = (data) => request.fulfill({ json: data });
+    switch (url.pathname) {
+      case "/boot.js":
+        return request.fulfill({ contentType: "text/javascript", body: `window.bootPrefs = {lang:"${lang}",theme:"light",web:true};` });
+      case "/wails/runtime.js":
+        return request.fulfill({ contentType: "text/javascript", body: "export const Window = {};" });
+      case "/api/state":
+        return json({ agents: [{ id: "codex", name: "Codex", path: "/test/codex", fields: [] }], profiles: [], settings: { lang, theme: "light" } });
+      case "/api/gateway/trace":
+        if (url.searchParams.has("wait")) return new Promise(() => {});
+        return json({ mine: true, now: iso(now), seq: 7, totals: { requests: 1, rerouted: 1, errors: 0 }, routes: [route(liveOrder, iso(now - 2000))] });
+      case "/api/gateway/history":
+        return json({ days: [{ day: keptDay, requests: 1 }], routes: url.searchParams.get("day") ? [route(liveOrder, keptDay + "T12:00:00Z")] : [] });
+      case "/api/usage/quotas": {
+        if (url.searchParams.has("asked")) refreshes.push(url.search);
+        return json(cards(refreshes.length > 0));
+      }
+      case "/api/usage/quotas/history":
+        return json([]);
+      case "/api/groups":
+        return json({ models: [], groups: [], pools: [] });
+      case "/api/providers":
+        return json({ providers: [], presets: [], excluded: [], gateway: { running: true, window: true, url: "http://127.0.0.1:3999" } });
+      default: {
+        if (url.pathname.startsWith("/api/")) return json({});
+        const file = path.join(assets, url.pathname === "/" ? "index.html" : url.pathname);
+        const contentType = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml", ".png": "image/png" }[path.extname(file)];
+        return request.fulfill({ body: await fs.readFile(file), contentType });
+      }
+    }
+  };
+}
+
+for (const engine of process.env.BROWSER ? [process.env.BROWSER] : ["chromium", "webkit"]) {
+  test(`${engine}: Routing shows the cached balance of the correct provider or key`, async (suite) => {
+    const browser = await (engine === "webkit" ? webkit.launch() : chromium.launch({ channel: process.env.CHROMIUM_CHANNEL || "chromium" }));
+    suite.after(() => browser.close());
+    for (const lang of ["en", "zh", "zh-TW", "ja", "de"]) {
+      await suite.test(lang, async () => {
+        const context = await browser.newContext({ viewport: { width: 1100, height: 760 }, reducedMotion: "reduce" });
+        try {
+          const page = await context.newPage();
+          const errors = [], refreshes = [];
+          page.setDefaultTimeout(5000);
+          page.on("pageerror", (error) => errors.push(error.message));
+          await page.route("**/*", serve(lang, refreshes));
+          await page.goto("http://magpie.test/?view=routing");
+          const row = (name) => page.locator(".rt-acts .rt-act").filter({ has: page.getByText(name, { exact: true }) });
+          await row("opus").waitFor();
+          await page.waitForFunction(() => Array.isArray(quotas) && quotas.some((card) => card.provider === "relay"));
+          await page.evaluate(() => new Promise((done) => requestAnimationFrame(() => requestAnimationFrame(done))));
+          assert.match(await row("opus").innerText(), /\$-2\.50/, "the failed relay request still shows its token balance");
+          assert.equal(await row("opus").locator(".tally .bad").isVisible(), true, "the failure tally stays visible");
+          assert.match(await row("opus").locator("[title*='Vendor timed out']").getAttribute("title"), /\$-2\.50/);
+          assert.match(await row("codex").innerText(), /\$37\.25/);
+          assert.equal(await row("codex").locator(".tally").isVisible(), true, "the success tally stays visible");
+          assert.match(await row("Primary").innerText(), /\$0\.00/);
+          assert.match(await row("Second").innerText(), /\$42\.35/);
+          assert.match(await row("Second").locator("[title*='Credit']").getAttribute("title"), /\$0\.25/);
+          assert.doesNotMatch(await row("Same name").innerText(), /\$/);
+          assert.doesNotMatch(await row("unread").innerText(), /\$/);
+          assert.equal(await row("read-failed").locator('[title="Balance API unavailable"]').count(), 1);
+          assert.deepEqual(refreshes, []);
+
+          const refresh = page.locator("#rtReadAllowances");
+          await refresh.waitFor({ state: "visible" });
+          await refresh.dispatchEvent("click");
+          await row("opus").getByText(/\$4\.20/).waitFor();
+          assert.deepEqual(refreshes, ["?asked=1&all=1"]);
+
+          const history = page.locator(".rt-days > .rt-day:not(.rt-day-more)").nth(1);
+          await history.waitFor({ state: "visible" });
+          await history.dispatchEvent("click");
+          await refresh.waitFor({ state: "hidden" });
+          await row("opus").waitFor();
+          assert.doesNotMatch(await row("opus").innerText(), /\$/);
+          assert.deepEqual(errors, []);
+        } finally {
+          await context.close();
+        }
+      });
+    }
+  });
+}
